import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { Row, Col, Card, Button, InputGroup, Form } from 'react-bootstrap';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faShoppingCart, faTrashAlt } from '@fortawesome/free-solid-svg-icons';
import axios from 'axios';

const Cart = () => {
  const [cartItems, setCartItems] = useState([]);
  const [subtotal, setSubtotal] = useState(0);
  const [shippingFee, setShippingFee] = useState(30000);
  const [discount, setDiscount] = useState(0);
  const [total, setTotal] = useState(0);
  const [couponCode, setCouponCode] = useState('');

  useEffect(() => {
    fetchCartItems();
  }, []);

  useEffect(() => {
    calculateTotals();
  }, [cartItems]);

  const fetchCartItems = async () => {
    try {
      const response = await axios.get('/api/cart');
      setCartItems(response.data);
    } catch (error) {
      console.error('Error fetching cart items:', error);
    }
  };

  const calculateTotals = () => {
    const newSubtotal = cartItems.reduce((sum, item) => sum + (item.manga.price * item.quantity), 0);
    setSubtotal(newSubtotal);
    setTotal(newSubtotal + shippingFee - discount);
  };

  const handleQuantityChange = async (itemId, change) => {
    try {
      const item = cartItems.find(item => item.id === itemId);
      const newQuantity = typeof change === 'string' ? parseInt(change) : item.quantity + change;

      if (newQuantity >= 1 && newQuantity <= 99) {
        await axios.post(`/api/cart/update/${itemId}`, { quantity: newQuantity });
        await fetchCartItems();
      }
    } catch (error) {
      console.error('Error updating quantity:', error);
    }
  };

  const handleRemoveItem = async (itemId) => {
    if (window.confirm('Bạn có chắc muốn xóa sản phẩm này khỏi giỏ hàng?')) {
      try {
        await axios.post(`/api/cart/remove/${itemId}`);
        await fetchCartItems();
      } catch (error) {
        console.error('Error removing item:', error);
      }
    }
  };

  const handleApplyCoupon = async () => {
    try {
      const response = await axios.post('/api/cart/apply-coupon', { couponCode });
      if (response.data.success) {
        setDiscount(response.data.discount);
        setCouponCode('');
      } else {
        alert(response.data.message);
      }
    } catch (error) {
      console.error('Error applying coupon:', error);
    }
  };

  if (cartItems.length === 0) {
    return (
      <div className="text-center py-5">
        <FontAwesomeIcon icon={faShoppingCart} size="4x" className="text-muted mb-3" />
        <h3>Giỏ hàng trống</h3>
        <p className="text-muted">Hãy thêm sản phẩm vào giỏ hàng của bạn</p>
        <Link to="/" className="btn btn-primary mt-3">Tiếp tục mua sắm</Link>
      </div>
    );
  }

  return (
    <>
      <h1 className="mb-4">Giỏ hàng của bạn</h1>

      <Row>
        <Col lg={8}>
          <Card className="mb-4">
            <Card.Body>
              {cartItems.map(item => (
                <Row key={item.id} className="mb-4 border-bottom pb-4">
                  <Col md={2}>
                    <img src={item.manga.coverImage} className="img-fluid rounded" alt={item.manga.title} />
                  </Col>
                  <Col md={5}>
                    <h5 className="card-title">{item.manga.title}</h5>
                    <p className="text-muted mb-2">
                      <small>
                        Tác giả: <Link to={`/author/${item.manga.author.id}`}>{item.manga.author.name}</Link>
                      </small>
                    </p>
                    <Button
                      variant="link"
                      className="text-danger p-0"
                      onClick={() => handleRemoveItem(item.id)}
                    >
                      <FontAwesomeIcon icon={faTrashAlt} /> Xóa
                    </Button>
                  </Col>
                  <Col md={3}>
                    <InputGroup style={{ width: '120px' }}>
                      <Button
                        variant="outline-secondary"
                        onClick={() => handleQuantityChange(item.id, -1)}
                      >
                        -
                      </Button>
                      <Form.Control
                        type="number"
                        value={item.quantity}
                        onChange={(e) => handleQuantityChange(item.id, e.target.value)}
                        className="text-center"
                        min="1"
                        max="99"
                      />
                      <Button
                        variant="outline-secondary"
                        onClick={() => handleQuantityChange(item.id, 1)}
                      >
                        +
                      </Button>
                    </InputGroup>
                  </Col>
                  <Col md={2} className="text-end">
                    <p className="price mb-0">
                      {(item.manga.price * item.quantity).toLocaleString('vi-VN')} đ
                    </p>
                  </Col>
                </Row>
              ))}
            </Card.Body>
          </Card>
        </Col>

        <Col lg={4}>
          <Card>
            <Card.Body>
              <h5 className="card-title mb-4">Tổng đơn hàng</h5>
              
              <div className="d-flex justify-content-between mb-3">
                <span>Tạm tính</span>
                <span className="price">
                  {subtotal.toLocaleString('vi-VN')} đ
                </span>
              </div>
              
              <div className="d-flex justify-content-between mb-3">
                <span>Phí vận chuyển</span>
                <span className="price">
                  {shippingFee.toLocaleString('vi-VN')} đ
                </span>
              </div>

              <div className="d-flex justify-content-between mb-3">
                <span>Giảm giá</span>
                <span className="text-danger">
                  -{discount.toLocaleString('vi-VN')} đ
                </span>
              </div>

              <hr />

              <div className="d-flex justify-content-between mb-4">
                <strong>Tổng cộng</strong>
                <strong className="price">
                  {total.toLocaleString('vi-VN')} đ
                </strong>
              </div>

              <div className="mb-4">
                <InputGroup>
                  <Form.Control
                    type="text"
                    placeholder="Mã giảm giá"
                    value={couponCode}
                    onChange={(e) => setCouponCode(e.target.value)}
                  />
                  <Button variant="outline-primary" onClick={handleApplyCoupon}>
                    Áp dụng
                  </Button>
                </InputGroup>
              </div>

              <Link to="/checkout" className="btn btn-primary w-100">
                Tiến hành thanh toán
              </Link>
            </Card.Body>
          </Card>
        </Col>
      </Row>
    </>
  );
};

export default Cart;
